"""Generates tests/sql/02_kpi_baselines.sql, tests/sql/03_source_reconciliation.sql and tests/dax/test_cases.json
from tests/baselines/expected_kpis.json (computed independently by tools/compute_baselines.py)."""
import json, os
import model_spec as ms
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
B = json.load(open(os.path.join(ROOT, "tests", "baselines", "expected_kpis.json")))
def w(path, text):
    full = os.path.join(ROOT, path); os.makedirs(os.path.dirname(full), exist_ok=True); open(full, "w", newline="\n").write(text)
HDR = "-- GENERATED by tools/build_repo.py from tests/baselines/expected_kpis.json - do not edit by hand.\n"

def cases():
    """(name, expected, T-SQL expression against dw.*, DAX expression, tolerance)"""
    S, P, I, H, Q = B["sales"], B["purchasing"], B["inventory"], B["hr"], B["quota"]
    jd = "JOIN dw.dim_date AS d ON d.date_key = f.order_date_key"
    c = [
     ("sales: net sales (total)", S["net_sales_total"], "(SELECT SUM(net_sales_amount) FROM dw.fact_sales_line)", "[Net Sales]", 0.5),
     ("sales: COGS (total)", S["cogs_total"], "(SELECT SUM(standard_cost_amount) FROM dw.fact_sales_line)", "[COGS]", 0.5),
     ("sales: gross margin % (total)", S["gross_margin_pct"], "(SELECT CAST(SUM(gross_margin_amount) AS float) / SUM(net_sales_amount) FROM dw.fact_sales_line)", "[Gross Margin %]", 1e-6),
     ("sales: total billed (= SUM TotalDue)", S["total_billed"], "(SELECT SUM(net_sales_amount + allocated_freight_amount + allocated_tax_amount) FROM dw.fact_sales_line)", "[Total Billed]", 1.0),
     ("sales: orders", S["orders"], "(SELECT COUNT(DISTINCT sales_order_id) FROM dw.fact_sales_line)", "[Orders]", 0),
    ]
    for fy, v in S["net_sales_by_fiscal_year"].items():
        n = int(fy[2:])
        c.append((f"sales: net sales {fy}", v, f"(SELECT SUM(f.net_sales_amount) FROM dw.fact_sales_line AS f {jd} WHERE d.fiscal_year = {n})", f"CALCULATE ( [Net Sales], 'Date'[Fiscal Year] = {n} )", 0.5))
    for t, v in S["net_sales_by_territory"].items():
        c.append((f"sales: net sales territory {t}", v, f"(SELECT SUM(f.net_sales_amount) FROM dw.fact_sales_line AS f JOIN dw.dim_territory AS t ON t.territory_key = f.territory_key WHERE t.territory_name = N'{t}')", f'CALCULATE ( [Net Sales], Territory[Territory] = "{t}" )', 0.5))
    c += [
     ("time intel: YoY growth FY2025", S["yoy_fy2025"], "(SELECT CAST(SUM(CASE WHEN d.fiscal_year = 2025 THEN f.net_sales_amount END) AS float) / SUM(CASE WHEN d.fiscal_year = 2024 THEN f.net_sales_amount END) - 1 FROM dw.fact_sales_line AS f " + jd + ")", "CALCULATE ( [Net Sales YoY Growth %], 'Date'[Fiscal Year] = 2025 )", 1e-6),
     ("time intel: fiscal YTD at Dec-2024", S["net_sales_fiscal_ytd_202412"], "(SELECT SUM(f.net_sales_amount) FROM dw.fact_sales_line AS f " + jd + " WHERE f.order_date_key BETWEEN 20240701 AND 20241231)", "CALCULATE ( [Net Sales YTD (Fiscal)], 'Date'[Year Month Number] = 202412 )", 0.5),
     ("time intel: rolling 3M average at Jun-2025", S["rolling_3m_avg_202506"], "(SELECT SUM(f.net_sales_amount) / 3.0 FROM dw.fact_sales_line AS f WHERE f.order_date_key BETWEEN 20250401 AND 20250630)", "CALCULATE ( [Net Sales Rolling 3M Avg], 'Date'[Year Month Number] = 202506 )", 0.5),
     ("finance: gross margin % FY2024", S["gross_margin_pct_fy2024"], "(SELECT CAST(SUM(f.gross_margin_amount) AS float) / SUM(f.net_sales_amount) FROM dw.fact_sales_line AS f " + jd + " WHERE d.fiscal_year = 2024)", "CALCULATE ( [Gross Margin %], 'Date'[Fiscal Year] = 2024 )", 1e-6),
     ("quota: quota FY2024", Q["quota_fy2024"], "(SELECT SUM(q.quota_amount) FROM dw.fact_sales_quota AS q JOIN dw.dim_date AS d ON d.date_key = q.quota_month_key WHERE d.fiscal_year = 2024)", "CALCULATE ( [Sales Quota], 'Date'[Fiscal Year] = 2024 )", 0.5),
     ("quota: attainment FY2024", Q["attainment_fy2024"], "(SELECT CAST(SUM(f.net_sales_amount) AS float) / (SELECT SUM(q.quota_amount) FROM dw.fact_sales_quota AS q JOIN dw.dim_date AS dq ON dq.date_key = q.quota_month_key WHERE dq.fiscal_year = 2024) FROM dw.fact_sales_line AS f " + jd + " JOIN dw.dim_salesperson AS s ON s.salesperson_key = f.salesperson_key WHERE d.fiscal_year = 2024 AND s.quota_status = N'Quota-carrying')", "CALCULATE ( [Quota Attainment %], 'Date'[Fiscal Year] = 2024 )", 1e-6),
     ("supply chain: purchase spend", P["spend_total"], "(SELECT SUM(line_total_amount) FROM dw.fact_purchase_line)", "[Purchase Spend]", 0.5),
     ("supply chain: on-time delivery %", P["on_time_pct"], "(SELECT CAST(SUM(on_time_flag) AS float) / SUM(shipped_flag) FROM dw.fact_purchase_line)", "[On-Time Delivery %]", 1e-6),
     ("supply chain: receipt fill rate %", P["fill_rate"], "(SELECT CAST(SUM(received_quantity) AS float) / SUM(order_quantity) FROM dw.fact_purchase_line)", "[Receipt Fill Rate %]", 1e-6),
     ("supply chain: reject rate %", P["reject_rate"], "(SELECT CAST(SUM(rejected_quantity) AS float) / SUM(received_quantity) FROM dw.fact_purchase_line)", "[Reject Rate %]", 1e-6),
     ("supply chain: inventory value", I["inventory_value"], "(SELECT SUM(inventory_value_amount) FROM dw.fact_inventory)", "[Inventory Value]", 0.5),
     ("supply chain: products below reorder point", I["products_below_reorder_point"], "(SELECT COUNT(*) FROM (SELECT i.product_key FROM dw.fact_inventory AS i JOIN dw.dim_product AS p ON p.product_key = i.product_key GROUP BY i.product_key, p.reorder_point HAVING SUM(i.quantity) < p.reorder_point) AS x)", "[Products Below Reorder Point]", 0),
     ("hr: headcount Dec-2010", H["headcount_201012"], "(SELECT SUM(headcount_flag) FROM dw.fact_headcount_monthly WHERE month_end_date_key = 20101231)", "CALCULATE ( [Headcount], 'Date'[Year Month Number] = 201012 )", 0),
     ("hr: headcount Jun-2025", H["headcount_202506"], "(SELECT SUM(headcount_flag) FROM dw.fact_headcount_monthly WHERE month_end_date_key = 20250630)", "CALCULATE ( [Headcount], 'Date'[Year Month Number] = 202506 )", 0),
     ("hr: est. payroll cost Jun-2025", H["payroll_cost_202506"], "(SELECT SUM(estimated_payroll_cost) FROM dw.fact_payroll_monthly WHERE month_end_date_key = 20250630)", "CALCULATE ( [Est. Payroll Cost], 'Date'[Year Month Number] = 202506 )", 1.0),
    ]
    for t, v in P["spend_by_territory"].items():
        c.append((f"supply chain: purchase spend, vendor region {t}", v, f"(SELECT SUM(f.line_total_amount) FROM dw.fact_purchase_line AS f JOIN dw.dim_territory AS t ON t.territory_key = f.territory_key WHERE t.territory_name = N'{t}')", f'CALCULATE ( [Purchase Spend], Territory[Territory] = "{t}" )', 0.5))
    assert len(H["headcount_by_territory"]) == 10
    for t, v in H["headcount_by_territory"].items():
        c.append((f"hr: headcount Jun-2025, home region {t}", v, f"(SELECT SUM(h.headcount_flag) FROM dw.fact_headcount_monthly AS h JOIN dw.dim_territory AS t ON t.territory_key = h.territory_key WHERE h.month_end_date_key = 20250630 AND t.territory_name = N'{t}')", f'CALCULATE ( [Headcount], \'Date\'[Year Month Number] = 202506, Territory[Territory] = "{t}" )', 0))
    return c

def gen_sql_baselines():
    o = [HDR, "-- 02_kpi_baselines.sql : compares KPIs computed from dw.* with values computed independently (pandas) straight from the raw AdventureWorks files.\nSET NOCOUNT ON;\n",
         "CREATE TABLE #t (test_name nvarchar(200) NOT NULL, expected float NOT NULL, actual float NULL, tolerance float NOT NULL);\n"]
    for name, exp, sql, dax, tol in cases():
        o.append(f"INSERT INTO #t VALUES (N'{name}', {exp!r}, {sql}, {tol!r});\n")
    o.append("""SELECT test_name, expected, actual, tolerance,
       CASE WHEN actual IS NOT NULL AND ABS(expected - actual) <= tolerance THEN N'PASS' ELSE N'FAIL' END AS status
FROM #t ORDER BY CASE WHEN actual IS NOT NULL AND ABS(expected - actual) <= tolerance THEN 1 ELSE 0 END, test_name;
DECLARE @fail int = (SELECT COUNT(*) FROM #t WHERE actual IS NULL OR ABS(expected - actual) > tolerance);
DECLARE @n int = (SELECT COUNT(*) FROM #t);
PRINT CONCAT(@n - @fail, ' of ', @n, ' KPI baseline tests passed');
IF @fail > 0
BEGIN
    THROW 52000, N'KPI baseline mismatch - see result set above.', 1;
END;
""")
    w("tests/sql/02_kpi_baselines.sql", "".join(o))

def gen_recon():
    import model_spec as m
    rows = []
    for t, spec in m.STG.items():
        rows.append(f"SELECT N'{t}' AS table_name, (SELECT COUNT_BIG(*) FROM src.{t}) AS source_rows, (SELECT COUNT_BIG(*) FROM stg.{t}) AS staging_rows")
    sql = HDR + ("-- 03_source_reconciliation.sql : LOCAL mode only (needs the src.* synonyms from sql/02b_source_synonyms.sql).\n"
                 "-- Proves staging == source (row counts) and the warehouse ties to the SOURCE tables, not just to staging.\nSET NOCOUNT ON;\n"
                 "CREATE TABLE #r (table_name nvarchar(128), source_rows bigint, staging_rows bigint);\nINSERT INTO #r\n" + "\nUNION ALL ".join(rows) + ";\n"
                 "SELECT table_name, source_rows, staging_rows, CASE WHEN source_rows = staging_rows THEN N'PASS' ELSE N'FAIL' END AS status FROM #r ORDER BY status, table_name;\n"
                 "DECLARE @bad int = (SELECT COUNT(*) FROM #r WHERE source_rows <> staging_rows);\n"
                 "DECLARE @ns_src decimal(38,6) = (SELECT SUM(LineTotal) FROM src.SalesOrderDetail), @ns_dw decimal(38,6) = (SELECT SUM(net_sales_amount) FROM dw.fact_sales_line);\n"
                 "DECLARE @td_src decimal(38,6) = (SELECT SUM(TotalDue) FROM src.SalesOrderHeader), @td_dw decimal(38,6) = (SELECT SUM(net_sales_amount + allocated_freight_amount + allocated_tax_amount) FROM dw.fact_sales_line);\n"
                 "SELECT N'net sales: source SUM(LineTotal) vs dw' AS test_name, @ns_src AS source_value, @ns_dw AS dw_value, CASE WHEN ABS(@ns_src - @ns_dw) <= 0.05 THEN N'PASS' ELSE N'FAIL' END AS status\n"
                 "UNION ALL SELECT N'billed: source SUM(TotalDue) vs dw', @td_src, @td_dw, CASE WHEN ABS(@td_src - @td_dw) <= 1.0 THEN N'PASS' ELSE N'FAIL' END;\n"
                 "IF @bad > 0 OR ABS(@ns_src - @ns_dw) > 0.05 OR ABS(@td_src - @td_dw) > 1.0\nBEGIN\n    THROW 52001, N'Source reconciliation failed - see result sets above.', 1;\nEND;\nPRINT 'Source reconciliation passed';\n")
    w("tests/sql/03_source_reconciliation.sql", sql)

def gen_dax():
    cs = []
    for name, exp, sql, dax, tol in cases():
        cs.append({"name": name, "dax": f'EVALUATE ROW ( "v", {dax} )', "expected": exp, "tolerance": tol})
    S = B["sales"]["net_sales_by_territory"]; eu = S["France"] + S["Germany"] + S["United Kingdom"]
    rls = [("rls: Northwest manager sees 1 territory", "northwest.manager@contoso.com", "[Territories Visible]", 1, 0),
           ("rls: Northwest manager net sales = Northwest only", "northwest.manager@contoso.com", "[Net Sales]", S["Northwest"], 0.5),
           ("rls: Canada manager net sales = Canada only", "canada.manager@contoso.com", "[Net Sales]", S["Canada"], 0.5),
           ("rls: Europe director sees 3 territories", "europe.director@contoso.com", "[Territories Visible]", 3, 0),
           ("rls: Europe director net sales = FR+DE+UK", "europe.director@contoso.com", "[Net Sales]", eu, 0.5),
           ("rls: unmapped user sees 0 territories (deny by default)", "nobody@contoso.com", "[Territories Visible]", 0, 0)]
    for name, user, dax, exp, tol in rls:
        cs.append({"name": name, "dax": f'EVALUATE ROW ( "v", COALESCE ( {dax}, 0 ) )', "expected": exp, "tolerance": tol, "impersonate": user})
    json.dump(cs, open(os.path.join(ROOT, "tests", "dax", "test_cases.json"), "w"), indent=1); open(os.path.join(ROOT, "tests", "dax", "test_cases.json"), "a").write("\n")
    return len(cs)

def run():
    gen_sql_baselines(); gen_recon(); return gen_dax()
